-- Personal online reports. No customer data is exposed through table endpoints.
-- Install once in Supabase SQL Editor. A local app registers its own publisher
-- by appending the INSERT generated by that app (a SHA-256 hash, never its key).
begin;

create table if not exists public.fleet_report_publishers (
  id uuid primary key,
  key_hash text not null unique check (key_hash ~ '^[0-9a-f]{64}$'),
  name text not null default 'Vlootanalyse',
  created_at timestamptz not null default now(),
  revoked_at timestamptz
);
create table if not exists public.fleet_reports (
  id uuid primary key,
  publisher_id uuid not null references public.fleet_report_publishers(id),
  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  payload jsonb not null check (jsonb_typeof(payload) = 'object' and octet_length(payload::text) <= 3145728),
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  expires_at timestamptz,
  revoked_at timestamptz
);
alter table public.fleet_report_publishers enable row level security;
alter table public.fleet_reports enable row level security;
revoke all on public.fleet_report_publishers, public.fleet_reports from public, anon, authenticated;

create or replace function public.fleet_report_ping(p_publisher_key text)
returns boolean language sql security definer set search_path = '' as $$
  select exists(select 1 from public.fleet_report_publishers
    where key_hash = encode(sha256(convert_to(p_publisher_key, 'UTF8')), 'hex') and revoked_at is null);
$$;

create or replace function public.fleet_report_publish(
  p_publisher_key text, p_report_id uuid, p_token_hash text,
  p_payload jsonb, p_expires_at timestamptz default null
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare publisher uuid; saved public.fleet_reports;
begin
  select id into publisher from public.fleet_report_publishers
    where key_hash = encode(sha256(convert_to(p_publisher_key, 'UTF8')), 'hex') and revoked_at is null;
  if publisher is null then raise exception 'Publiceren is niet ingesteld.' using errcode = '42501'; end if;
  if p_token_hash !~ '^[0-9a-f]{64}$' or p_token_hash is null
     or p_payload->>'schema_version' is distinct from '1'
     or jsonb_typeof(p_payload->'variants') is distinct from 'array'
     or jsonb_array_length(p_payload->'variants') < 1
     or octet_length(p_payload::text) > 3145728 then
    raise exception 'Ongeldig rapport.' using errcode = '22023';
  end if;
  if p_expires_at is not null and p_expires_at <= now() then
    raise exception 'Kies een vervaldatum in de toekomst.' using errcode = '22023';
  end if;
  insert into public.fleet_reports(id, publisher_id, token_hash, payload, expires_at)
    values (p_report_id, publisher, p_token_hash, p_payload, p_expires_at)
    on conflict(id) do update set payload = excluded.payload,
      expires_at = excluded.expires_at, updated_at = now(), revision = fleet_reports.revision + 1
    where fleet_reports.publisher_id = publisher and fleet_reports.revoked_at is null
      and fleet_reports.token_hash = excluded.token_hash
    returning * into saved;
  if saved.id is null then raise exception 'Deze link kan niet worden bijgewerkt.' using errcode = '42501'; end if;
  return jsonb_build_object('id', saved.id, 'revision', saved.revision,
    'updated_at', saved.updated_at, 'expires_at', saved.expires_at);
end;
$$;

create or replace function public.fleet_report_read(p_token_hash text)
returns jsonb language sql security definer set search_path = '' as $$
  select r.payload || jsonb_build_object('publication', jsonb_build_object(
    'revision', r.revision, 'updated_at', r.updated_at, 'expires_at', r.expires_at))
  from public.fleet_reports r join public.fleet_report_publishers p on p.id = r.publisher_id
  where r.token_hash = p_token_hash and p_token_hash ~ '^[0-9a-f]{64}$'
    and r.revoked_at is null and p.revoked_at is null
    and (r.expires_at is null or r.expires_at > now());
$$;

create or replace function public.fleet_report_revoke(p_publisher_key text, p_report_id uuid)
returns boolean language plpgsql security definer set search_path = '' as $$
declare publisher uuid;
begin
  select id into publisher from public.fleet_report_publishers
    where key_hash = encode(sha256(convert_to(p_publisher_key, 'UTF8')), 'hex') and revoked_at is null;
  if publisher is null then raise exception 'Publiceren is niet ingesteld.' using errcode = '42501'; end if;
  update public.fleet_reports set revoked_at = coalesce(revoked_at, now()), updated_at = now()
    where id = p_report_id and publisher_id = publisher;
  return found;
end;
$$;

revoke all on function public.fleet_report_ping(text) from public;
revoke all on function public.fleet_report_publish(text,uuid,text,jsonb,timestamptz) from public;
revoke all on function public.fleet_report_read(text) from public;
revoke all on function public.fleet_report_revoke(text,uuid) from public;
grant execute on function public.fleet_report_ping(text) to anon, authenticated;
grant execute on function public.fleet_report_publish(text,uuid,text,jsonb,timestamptz) to anon, authenticated;
grant execute on function public.fleet_report_read(text) to anon, authenticated;
grant execute on function public.fleet_report_revoke(text,uuid) to anon, authenticated;
notify pgrst, 'reload schema';
commit;
